const state={view:location.hash.slice(1)||'overview',profile:{...DEFAULT_PROFILE},items:[],catalogue:[],insights:null,registries:null,messages:[],busy:false,live:false,quoteAccepted:false,consent:false,gstInput:'',udyamInput:'',gstResult:null,udyamResult:null,documents:{},order:null,orderStep:0,category:'All products',search:'',modal:null,mobileNav:false,assistance:false,kycErrors:[],ocrBusy:false};
