function toast(message){const el=document.createElement('div');el.className='toast';el.innerHTML=`${icon('check')}<span>${e(message)}</span>`;$('#toasts').append(el);setTimeout(()=>el.remove(),4500);}
function navigate(view){state.view=view;state.mobileNav=false;state.modal=null;location.hash=view;render();window.scrollTo({top:0,behavior:'smooth'});}
