function overview(){return `${title('A LITTLE LESS COMPLEX. A LOT MORE POSSIBLE.',tr('Hello, business builder.','नमस्ते, बिज़नेस बिल्डर।'),tr('Let’s make your next big move a little simpler.','आपके अगले बड़े कदम को थोड़ा आसान बनाते हैं।'),`<span class="edition">airtel <b>sync</b><sup>2026</sup></span>`)}<section class="hero"><div class="hero-copy"><span class="hero-kicker"><span></span> YOUR NEXT CHAPTER STARTS HERE</span><h2>${tr('Big ambitions.<br>One simple start.','बड़े इरादे।<br>एक आसान शुरुआत।')}</h2><p>${tr('Internet. Business tools. Peace of mind.<br>The right digital setup for your business,<br>all in one place.','इंटरनेट, बिज़नेस टूल्स और मन की शांति।<br>आपके व्यवसाय के लिए सही डिजिटल सेटअप,<br>एक ही जगह।')}</p><div class="hero-actions">${btn(`${tr('Find my perfect bundle','मेरा सही बंडल खोजें')} ${icon('arrow')}`,'start')}<button class="text-button" data-action="nav" data-view="products">${tr('Explore products','प्रोडक्ट देखें')} ${icon('chevron')}</button></div><div class="hero-proof"><span class="proof-avatars"><i>क</i><i>A</i><i>ம</i></span><span>${tr('Your business. Your budget. Your language.','आपका व्यवसाय। आपका बजट। आपकी भाषा।')}</span></div></div>${shopIllustration()}</section><div class="trust-strip"><span>${icon('catalogue')}25 business essentials</span><span>${icon('globe')}English, हिन्दी & தமிழ்</span><span>${icon('shield')}You control your data</span><span>${icon('users')}Human help when you need it</span></div><section class="journey-section"><div class="section-heading"><div><span class="eyebrow">LESS RUNNING AROUND. MORE RUNNING YOUR BUSINESS.</span><h2>Your digital journey, made simple</h2></div><span class="small-muted">Four steps. One connected business.</span></div><div class="journey-grid">${journey.map(([view,name,sub],i)=>`<button class="journey-step" data-action="nav" data-view="${view}"><span class="journey-number">0${i+1}</span><div><b>${name}</b><p>${sub}</p></div>${icon('arrow')}</button>`).join('')}</div></section><section class="product-section"><div class="section-heading"><div><span class="eyebrow">THE BUILDING BLOCKS OF BETTER BUSINESS</span><h2>A little of what you need. None of what you don’t.</h2></div><button class="text-button" data-action="nav" data-view="products">View all products ${icon('arrow')}</button></div><div class="feature-grid">${[['wifi','Connectivity that keeps up','From the first customer to the last call. Business internet that works as hard as you do.','Connectivity','From ₹899','signal'],['cloud','Tools to do more, together','Professional email, shared files and backups. Give good work a better home.','Cloud & Productivity','From ₹125','cloud-art'],['shield','One less thing to worry about','Protect your devices and business data, so you can focus on what’s next.','Security','From ₹99','security-art']].map(([ic,name,desc,cat,price,art])=>`<button class="feature-card" data-action="category" data-category="${cat}"><div class="feature-top"><span class="feature-icon">${icon(ic)}</span><span class="feature-tag">${cat==='Cloud & Productivity'?'PRODUCTIVITY':cat.toUpperCase()}</span></div><div class="feature-art ${art}">${art==='signal'?'<i></i><i></i><i></i><i></i><i></i>':art==='cloud-art'?`${icon('mail')}${icon('file')}${icon('cloud')}`:`<span>${icon('shield')}</span>`}</div><h3>${name}</h3><p>${desc}</p><div class="feature-bottom"><span>${price}<small>/month · per unit</small></span>${icon('arrow')}</div></button>`).join('')}</div></section><section class="business-banner"><span class="banner-icon">${icon('store')}</span><div><h3>Built for the businesses that build India.</h3><p>From your first shop to your fifth location. There’s a starting point for you.</p></div><button class="text-button" data-action="start">Let’s find yours ${icon('arrow')}</button></section>`;}
function stepper(current){return `<div class="flow-stepper">${journey.map(([view,name],i)=>`<button class="flow-step ${i===current?'current':''} ${i<current?'complete':''}" data-action="nav" data-view="${view}" ${i===current?'aria-current="step"':''}><span>${i<current?icon('check'):i+1}</span><b>${name}</b></button>`).join('')}</div>`;}
function profileSummary(){const p=state.profile;return `<aside class="context-panel"><div class="context-top">${icon('store')}<span>YOUR BUSINESS AT A GLANCE</span></div><h3>${e(BUSINESS_TYPES.find(t=>t.id===p.type)?.name||'A fresh start')}</h3><p class="muted">A setup that fits the way you work.</p><dl><div><dt>Team size</dt><dd>${p.employees} people</dd></div><div><dt>Locations</dt><dd>${p.sites}</dd></div><div><dt>City</dt><dd>${e(p.city)} · Tier ${p.tier}</dd></div><div><dt>Monthly budget</dt><dd>${money(p.budget)}</dd></div><div><dt>GST registration</dt><dd>${p.hasGstin?'Available · not yet verified':'Not provided'}</dd></div></dl><div class="context-note">${icon('info')}<p>Recommendations use the case catalogue. Final eligibility is checked again before checkout.</p></div><div class="context-footer"><span class="mini-saathi">s.</span><p>A little clarity.<br><b>A lot of possibility.</b></p></div></aside>`;}
function advisor(){const p=state.profile;return `${stepper(0)}${title('01 / YOUR BUSINESS',tr('Good advice starts with you.','सही सलाह की शुरुआत आपसे होती है।'),tr('Tell us a little about your business. We’ll take it from there.','अपने व्यवसाय के बारे में थोड़ा बताइए। आगे हम साथ हैं।'))}<div class="advisor-layout"><section class="advisor-main"><div class="conversation-card"><div class="conversation-heading"><span class="saathi-avatar">s.</span><div><h3>Meet your Saathi</h3><span><i class="online-dot"></i> ${state.live?'Live AI advisor':'Catalogue-guided demo'} · ${hi()?'हिन्दी में बात करें':state.profile.language==='ta'?'தமிழில் பேசலாம்':'Here to make it simpler'}</span></div>${chip(state.live?'LIVE AI':'GUIDED DEMO',state.live?'green':'')}</div><div class="messages" aria-live="polite">${(state.messages.length?state.messages:[{role:'assistant',text:tr('Hi, I’m Saathi. What kind of business do you run? Tell me in your own words, or choose below.','नमस्ते, मैं साथी हूँ। आपका व्यवसाय किस प्रकार का है? अपने शब्दों में बताइए या नीचे से चुनिए।')}]).map(m=>`<div class="message ${m.role}">${m.role==='assistant'?'<span class="message-avatar">s.</span>':''}<div><p>${e(m.text)}</p>${m.source?`<span class="message-source">${e(m.source)}</span>`:''}</div></div>`).join('')}${state.busy?'<div class="thinking"><span></span><span></span><span></span><small>Saathi is thinking…</small></div>':''}</div><form id="chat-form" class="chat-form"><input id="chat-input" name="message" autocomplete="off" maxlength="1500" placeholder="${tr('e.g. I run a clinic in Delhi with 5 staff. Budget ₹3,500.','जैसे: दिल्ली में 5 कर्मचारियों का क्लिनिक है। बजट ₹3,500।')}" aria-label="Message your advisor" ${state.busy?'disabled':''}><button class="send-button" type="submit" aria-label="Send message" ${state.busy?'disabled':''}>${icon('arrow')}</button></form><div class="chat-hint">${icon('lock')}No documents or identity numbers needed here.</div></div><div class="form-card"><div class="form-section-title"><span>LET’S GET THE BASICS RIGHT</span><span>Or fill in the details below</span></div><label class="field-title">${tr('What kind of business do you run?','आपका व्यवसाय किस प्रकार का है?')}</label><div class="business-type-grid">${BUSINESS_TYPES.map(t=>`<button class="type-option ${p.type===t.id?'selected':''}" data-action="business-type" data-type="${t.id}" aria-pressed="${p.type===t.id}">${icon(t.icon)}<span>${hi()?t.hi:t.name}</span><i>${p.type===t.id?icon('check'):''}</i></button>`).join('')}</div><label class="field current-tools">Current internet & tools<input id="current-tools" data-field="currentTools" maxlength="300" value="${e(p.currentTools||'')}" placeholder="e.g. home broadband, Google Workspace, antivirus"><small>Already have a tool? We’ll avoid recommending it again.</small></label><div class="field-grid"><label class="field">Team size<input type="number" min="1" max="500" value="${p.employees}" data-field="employees" id="employees"><small>People who work with you</small></label><label class="field">Locations<input type="number" min="1" max="100" value="${p.sites}" data-field="sites" id="sites"><small>Shops, offices or branches</small></label><label class="field">City<select data-field="city" id="city">${['Delhi','Mumbai','Bengaluru','Chennai','Hyderabad','Kolkata','Pune','Jaipur','Lucknow','Indore','Kochi','Ludhiana','Surat','Coimbatore'].map(c=>`<option ${p.city===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Monthly budget (₹)<input type="number" min="500" max="1000000" step="100" value="${p.budget}" data-field="budget" id="budget"></label><label class="field">Internet preference<select data-field="internet" id="internet"><option value="fibre" ${p.internet==='fibre'?'selected':''}>Fibre broadband</option><option value="wireless" ${p.internet==='wireless'?'selected':''}>Wireless / no fibre available</option></select></label><label class="field">What matters most?<select data-field="priority" id="priority"><option value="reliability" ${p.priority==='reliability'?'selected':''}>Reliable, uninterrupted work</option><option value="budget" ${p.priority==='budget'?'selected':''}>Keeping costs low</option><option value="customers" ${p.priority==='customers'?'selected':''}>Reaching more customers</option></select></label></div><label class="check-row"><input type="checkbox" data-field="hasGstin" ${p.hasGstin?'checked':''}><span>My business has a GSTIN<small>We’ll verify it later. You can also start without one.</small></span></label><div class="form-bottom"><span>${icon('clock')}A small step towards a better setup.</span>${btn(`${tr('Show my recommendations','मेरा बंडल दिखाएँ')} ${icon('arrow')}`,'recommend','primary',!p.type?'disabled':'')}</div></div></section>${profileSummary()}</div>`;}
function emptyState(iconName,eyebrow,heading,desc,button,action){return `${title(eyebrow,heading,desc)}<div class="empty-state"><span>${icon(iconName)}</span><h2>Let’s start at the beginning.</h2><p>${desc}</p>${btn(`${button} ${icon('arrow')}`,action)}</div>`;}
function quoteView(){if(!state.items.length)return emptyState('box','02 / YOUR BUNDLE','A bundle with your name on it.','Tell us what your business needs, and we’ll put the right essentials together.','Find my bundle','start');const q=quote();return `${stepper(1)}${title('02 / YOUR BUNDLE',tr('Just right for your business.','आपके व्यवसाय के लिए सही।'),tr('A clear price. Useful essentials. Room to make it your own.','साफ़ कीमत। ज़रूरी टूल्स। आपकी पसंद की आज़ादी।'),btn(`${icon('back')} Edit business details`,'back-advisor','secondary'))}<div class="quote-layout"><div><section class="bundle-card"><div class="bundle-head"><div><span class="eyebrow">YOUR RECOMMENDED STARTING POINT</span><h2>${e(BUSINESS_TYPES.find(t=>t.id===state.profile.type)?.name||'Business')} essentials</h2><p>Selected for ${state.profile.employees} people · ${state.profile.sites} ${state.profile.sites===1?'location':'locations'} · ${e(state.profile.city)}</p></div><span class="bundle-mark">${icon('box')}</span></div><div class="bundle-lines">${q.lines.map(l=>`<article class="bundle-line"><span class="line-icon">${icon(categoryIcon(l.product))}</span><div class="line-description"><h3>${e(l.product.product_name)}</h3><p>${e(l.reason||l.product.description)}</p><span>${money(unitPrice(l.product))} ${e(l.product.unit)}/month · ${l.product.min_contract_months}-month minimum</span>${l.setup?`<span class="setup-tag">${money(l.setup)} one-time setup</span>`:''}</div><div class="line-control"><div class="quantity-control"><button data-action="quantity" data-id="${l.id}" data-delta="-1" aria-label="Reduce ${e(l.product.product_name)} quantity" ${l.qty<=1?'disabled':''}>${icon('minus')}</button><span>${l.qty}</span><button data-action="quantity" data-id="${l.id}" data-delta="1" aria-label="Increase ${e(l.product.product_name)} quantity">${icon('plus')}</button></div><b>${money(l.monthly)}<small>/mo</small></b><button class="remove-button" data-action="remove-product" data-id="${l.id}">Remove</button></div></article>`).join('')}</div><button class="add-more" data-action="nav" data-view="products">${icon('plus')} Add something to your bundle ${icon('arrow')}</button></section><div class="quote-notes"><div>${icon('info')}<p>Demo prices use the lower end of each supplied catalogue range. Taxes are excluded; serviceability and final commercial terms need operator confirmation.</p></div><div>${icon('clock')}<p>Digital onboarding can finish here. Physical installation still takes time—your longest selected product has a typical ${q.installDays}-day installation window.</p></div></div>${q.errors.length?`<div class="alert error">${icon('info')}<div><b>Let’s fix these before moving on</b>${q.errors.map(err=>`<p>${e(err)}</p>`).join('')}</div></div>`:''}</div><aside class="quote-summary"><div class="summary-heading">ONE BUNDLE. ONE CLEAR VIEW.</div><h3>Your monthly total</h3><div class="total-price">${money(q.monthly)}<span>/month</span></div><span class="tax-note">Excluding taxes · synthetic catalogue prices</span><div class="budget-meter ${q.overBudget?'over':''}"><div style="width:${Math.min(100,q.monthly/state.profile.budget*100)}%"></div></div><div class="budget-caption"><span>${q.overBudget?'Above your budget':'Within your budget'}</span><b>${money(state.profile.budget)}/mo</b></div><dl class="summary-totals"><div><dt>Monthly recurring</dt><dd>${money(q.monthly)}</dd></div><div><dt>One-time setup</dt><dd>${money(q.setup)}</dd></div><div><dt>First month + setup</dt><dd>${money(q.monthly+q.setup)}</dd></div><div><dt>Longest minimum contract</dt><dd>${q.contract} months</dd></div></dl>${btn(`Looks good. Let’s verify ${icon('arrow')}`,'accept-quote','primary full',q.errors.length?'disabled':'')}<p class="checkout-note">${icon('lock')}No payment collected in this prototype.</p><div class="summary-help"><b>Want a second opinion?</b><button class="text-button" data-action="support">Talk to a business expert ${icon('arrow')}</button></div></aside></div>`;}
function products(){const filtered=state.catalogue.filter(p=>(state.category==='All products'||p.category===state.category)&&`${p.product_name} ${p.description} ${p.category}`.toLowerCase().includes(state.search.toLowerCase()));return `${title('THE RIGHT TOOLS. A BETTER EVERYDAY.','Small essentials. Big possibilities.','Explore 25 products from the supplied case catalogue. Build a bundle around what matters to you.',state.items.length?btn(`Your bundle · ${state.items.length} ${icon('arrow')}`,'nav-quote','primary'):'')}<div class="catalogue-toolbar"><div class="category-tabs" aria-label="Product categories">${['All products','Connectivity','Communication','Cloud & Productivity','Security','IoT & Physical'].map(c=>`<button class="${state.category===c?'selected':''}" data-action="category" data-category="${c}">${c==='Cloud & Productivity'?'Cloud & tools':c==='IoT & Physical'?'IoT & CCTV':c}</button>`).join('')}</div><label class="product-search">${icon('search')}<input id="product-search" placeholder="Find a product…" value="${e(state.search)}" aria-label="Search products"></label></div><p class="catalogue-count">${filtered.length} ${filtered.length===1?'product':'products'} · Prices exclude taxes and use catalogue starting rates</p><div class="catalogue-grid">${filtered.map(p=>{const added=state.items.some(i=>i.id===p.product_id);return `<article class="catalogue-card"><div class="catalogue-card-top"><span class="product-symbol">${icon(categoryIcon(p))}</span><span class="product-code">${p.product_id}</span></div><span class="eyebrow">${e(p.category)}</span><h3>${e(p.product_name)}</h3><p>${e(p.description)}</p><div class="product-terms"><span>${icon('clock')}${p.min_contract_months}-month minimum</span><span>${icon('pin')}Tier ${p.available_city_tiers.replace(';',' & ')} cities</span>${p.requires_gstin==='Y'?'<span>Active GSTIN required</span>':''}</div><div class="product-card-bottom"><div><strong>${money(unitPrice(p))}</strong><span>${e(p.unit)}/month</span></div><button class="round-button ${added?'added':''}" data-action="${added?'nav-quote':'product-detail'}" data-id="${p.product_id}" aria-label="${added?'View bundle':'View '+e(p.product_name)}">${icon(added?'check':'plus')}</button></div></article>`;}).join('')}</div>${!filtered.length?'<div class="no-results">No products match that search. Try “internet”, “email” or “security”.</div>':''}`;}
function docCard(kind,title,desc){const d=state.documents[kind];return `<div class="document-card ${d?'has-document':''}"><div class="document-icon">${icon(d?'file':'upload')}</div><div class="document-copy"><b>${title}</b><span>${d?e(d.name):desc}</span>${d?`<small class="${d.issues?.length?'red':'green-text'}">${d.status==='reading'?'Reading document…':d.status==='reviewed'?'Details confirmed for demo review':d.status==='needs-review'?'Please check the extracted details':'Ready for review'}</small>`:''}</div>${d&&d.status!=='reading'?`<button class="text-button" data-action="review-doc" data-kind="${kind}">Review ${icon('arrow')}</button>`:`<label class="upload-button ${!state.consent||state.ocrBusy?'disabled':''}">Choose file<input type="file" accept="image/png,image/jpeg,image/webp" data-upload="${kind}" ${!state.consent||state.ocrBusy?'disabled':''} aria-label="Upload ${title}"></label>`}${d?`<button class="icon-button" data-action="remove-doc" data-kind="${kind}" aria-label="Remove ${title}" ${state.ocrBusy?'disabled':''}>${icon('close')}</button>`:''}</div>`;}
function kyc(){if(!state.items.length||!state.quoteAccepted)return emptyState('shield','03 / QUICK VERIFICATION','A little paperwork. A lot less paper.','Review and accept your bundle before starting business verification.','Review my bundle','nav-quote');const q=quote();return `${stepper(2)}${title('03 / QUICK VERIFICATION',tr('Your business. In good hands.','आपका व्यवसाय। सुरक्षित हाथों में।'),tr('A few checks to get things moving. You stay in control of your data.','कुछ आसान जाँच। अपने डेटा का नियंत्रण आपके हाथ में।'))}<div class="kyc-layout"><div class="kyc-main"><section class="consent-card"><div class="consent-icon">${icon('shield')}</div><div><h3>Your permission comes first.</h3><p>We’ll read your documents in this browser and check business identifiers against the supplied <b>mock registries</b>. Original images and identifiers stay in memory and are cleared when you refresh or reset the session.</p><label class="check-row"><input id="kyc-consent" type="checkbox" ${state.consent?'checked':''}><span>I agree to document extraction and mock registry checks for this onboarding demo.</span></label><button class="text-button" data-action="privacy">Read our privacy choices ${icon('arrow')}</button></div></section><section class="form-card"><div class="section-heading compact"><h3>01 &nbsp; Verify your business</h3>${chip('MOCK LOOKUPS')}</div><p class="muted">${q.gstRequired?'Your selected products require an active GSTIN.':'Use an active GSTIN or an Udyam registration. No GSTIN? You can still get started.'}</p><div class="registry-field"><label class="field" for="gst-input">GSTIN<input id="gst-input" autocomplete="off" maxlength="15" value="${e(state.gstInput)}" placeholder="15-character GSTIN" ${!state.consent?'disabled':''}></label>${btn('Verify GSTIN','verify-gst','secondary',!state.consent?'disabled':'')}</div>${registryResult(state.gstResult,'gst')}<div class="registry-field"><label class="field" for="udyam-input">Udyam registration ${q.gstRequired?'(optional)':''}<input id="udyam-input" autocomplete="off" maxlength="19" value="${e(state.udyamInput)}" placeholder="UDYAM-XX-00-1234567" ${!state.consent?'disabled':''}></label>${btn('Verify Udyam','verify-udyam','secondary',!state.consent?'disabled':'')}</div>${registryResult(state.udyamResult,'udyam')}<div class="demo-tools"><span>${icon('info')}Trying it out? Load fictional applicant K03.</span><button class="text-button" data-action="demo-registry" ${!state.consent?'disabled':''}>Load sample ${icon('arrow')}</button></div></section><section class="form-card"><div class="section-heading compact"><h3>02 &nbsp; Your supporting documents</h3><span class="small-muted">PNG, JPG or WebP · up to 8 MB each</span></div><p class="muted">Upload clear images, then confirm the extracted details. OCR runs on your device; an internet connection is needed to load the OCR engine.</p>${docCard('id','Signatory identity','ID of the person authorised to sign')}${docCard('address','Business address proof','Utility bill issued within the last 90 days')}${docCard('gst','GST certificate (optional)','Cross-check its GSTIN against your lookup')}${docCard('udyam','Udyam certificate (optional)','Cross-check the enterprise registration number')}<p class="case-date">${icon('clock')}Document age uses the case reference date: 15 July 2026.</p><div class="demo-tools"><span>Sample K03 · Ganesh Woodcraft · supplied fictional applicant.</span><button class="text-button" data-action="demo-docs" ${!state.consent||state.ocrBusy?'disabled':''}>Load sample documents ${icon('arrow')}</button></div></section>${state.kycErrors.length?`<div class="alert error">${icon('info')}<div><b>A few things need your attention</b>${state.kycErrors.map(x=>`<p>${e(x)}</p>`).join('')}</div></div>`:''}<div class="kyc-actions">${btn(`${icon('back')} Back to bundle`,'nav-quote','secondary')}${btn(`Submit demo order ${icon('arrow')}`,'place-order','primary',!state.consent||state.ocrBusy?'disabled':'')}</div></div><aside class="kyc-aside"><div class="safety-illustration">${icon('shield')}<span>${icon('check')}</span></div><span class="eyebrow">TRUST IS A TWO-WAY STREET</span><h3>Only what’s needed.<br>Only with permission.</h3><ul class="privacy-points"><li>${icon('check')}Documents read on your device</li><li>${icon('check')}No KYC sent to the AI advisor</li><li>${icon('check')}Identifiers masked in results</li><li>${icon('check')}Clear session data at any time</li></ul><div class="aside-divider"></div><h4>Your bundle</h4><p>${q.lines.length} products · ${money(q.monthly)}/month</p><p class="small-muted">This is a student prototype. No real verification, payment or service activation takes place.</p><button class="text-button" data-action="support">Need help with a document? ${icon('arrow')}</button></aside></div>`;}
function registryResult(result,kind){if(!result)return '';return `<div class="registry-result ${result.ok?'success':'error'}">${icon(result.ok?'check':'info')}<div><b>${e(result.message)}</b>${result.record?`<p>${e(result.record.legal_name||result.record.enterprise_name)}</p><span>${e(maskIdentifier(kind==='gst'?result.record.gstin:result.record.udyam_number))} · ${e(result.record.state)}${result.record.status?' · '+e(result.record.status):''}</span>`:''}</div></div>`;}
const ORDER_STAGES=[['Order received','Your bundle and submitted details are ready for demo review.','file'],['Business review','Documents and eligibility are being reviewed in this simulated journey.','shield'],['Installation planned','An installation partner would confirm serviceability and a time slot.','users'],['Ready to connect','Your services would activate after installation and final checks.','wifi']];
function tracker(){if(!state.order)return emptyState('box','04 / YOU’RE CONNECTED','Every step. In plain sight.','Your order will appear here after you choose a bundle and submit verification.','Find my bundle','start');const o=state.order;return `${title('04 / YOUR ORDER','Good things are getting connected.','Follow the journey without the follow-up calls.',chip('SIMULATED ORDER',''))}<div class="order-banner"><div class="order-icon">${icon('box')}</div><div><span>DEMO ORDER ${e(o.id)}</span><h2>${ORDER_STAGES[state.orderStep][0]}</h2><p>${ORDER_STAGES[state.orderStep][1]}</p></div>${chip(state.orderStep===3?'Demo complete':'In progress',state.orderStep===3?'green':'')}</div><div class="tracker-layout"><section class="timeline-card"><div class="section-heading compact"><h3>A clear view of what’s next</h3><span class="small-muted">No real service is being provisioned</span></div><div class="order-timeline">${ORDER_STAGES.map(([name,desc,ic],i)=>`<div class="timeline-item ${i<state.orderStep?'done':''} ${i===state.orderStep?'current':''}"><span class="timeline-icon">${icon(i<state.orderStep?'check':ic)}</span><div><span class="timeline-label">STEP 0${i+1} ${i===state.orderStep?'· YOU ARE HERE':''}</span><h3>${name}</h3><p>${desc}</p>${i===2?`<span class="installation-note">Catalogue-based typical installation: up to ${o.installDays} days; subject to serviceability.</span>`:''}</div></div>`).join('')}</div><div class="simulation-control"><div>${icon('refresh')}<span>Demo controls<small>Move through the simulated activation journey.</small></span></div>${btn(state.orderStep===3?'Restart simulation':`Simulate next step ${icon('arrow')}`,'advance-order','secondary')}</div></section><aside class="quote-summary"><span class="eyebrow">YOUR BUSINESS ESSENTIALS</span><h3>${o.lines.length} products. One place.</h3><div class="order-product-list">${o.lines.map(l=>`<div>${icon(categoryIcon(l.product))}<span>${e(l.product.product_name)}<small>Quantity: ${l.qty}</small></span><b>${money(l.monthly)}</b></div>`).join('')}</div><dl class="summary-totals"><div><dt>Monthly total</dt><dd>${money(o.monthly)}</dd></div><div><dt>Setup fees</dt><dd>${money(o.setup)}</dd></div></dl>${btn(`${icon('download')} Download order summary`,'download-order','secondary full')}<div class="summary-help"><b>A question along the way?</b><button class="text-button" data-action="support">Ask for partner assistance ${icon('arrow')}</button></div></aside></div>`;}
function partners(){const d=state.insights;return `${title('GOOD TECHNOLOGY. GREAT PEOPLE.','Digital starts it. People take it further.','A partner workspace for the conversations that need a human touch.',chip('SYNTHETIC CASE DATA'))}<div class="metrics-grid">${[['5,000','Leads in the case dataset','Apr–Jun 2026'],['7.36%','Baseline lead-to-activation','368 activated businesses'],['17.6 days','Baseline average activation','From the supplied case brief'],['11.1%','Professional-office conversion','138 of 1,247 supplied leads']].map(([n,label,sub])=>`<div class="metric-card"><span>${label}</span><strong>${n}</strong><small>${sub}</small></div>`).join('')}</div><div class="partner-layout"><section class="form-card"><div class="section-heading compact"><h3>A little help, where it matters</h3>${chip(`${state.assistance?1:0} REQUESTS`)}</div>${state.assistance?`<div class="partner-lead"><span class="product-symbol">${icon('store')}</span><div><h3>Current demo business</h3><p>${e(BUSINESS_TYPES.find(t=>t.id===state.profile.type)?.name||'Business exploring options')} · ${state.profile.employees} people · ${e(state.profile.city)}</p><small>Reason: requested help in the prototype. No message was sent externally.</small></div>${chip('NEEDS ASSISTANCE')}</div><div class="partner-next"><b>A useful next conversation</b><p>Review the customer’s bundle, confirm serviceability, and help resolve any document concerns. Let the owner approve every change.</p>${btn('Mark as reviewed','resolve-assistance','secondary')}</div>`:`<div class="partner-empty">${icon('users')}<h3>No one waiting right now.</h3><p>Requests made through “Talk to a business expert” appear here during this session.</p></div>`}</section><section class="form-card"><div class="section-heading compact"><h3>Where the opportunity is</h3><span class="small-muted">Observed conversion</span></div><div class="segment-bars">${(d?.segments||[]).map(s=>`<div><div><span>${e(s.name)}</span><b>${s.conversion}%</b></div><span class="bar-track"><i style="width:${s.conversion/15*100}%"></i></span><small>${s.activated} activations / ${s.leads} leads</small></div>`).join('')}</div><p class="small-muted">Observed results from synthetic data, not projected improvements or Airtel performance.</p></section></div><section class="business-banner"><span class="banner-icon">${icon('network')}</span><div><h3>Partners are part of the journey.</h3><p>Help with exceptions, confirm installation, and pick up where digital stops.</p></div></section>`;}
function footer(){return `<footer class="footer"><span>Made with intent. <b>Ping Me Maybe.</b></span><span>Airtel Sync 2026 · Independent student prototype <i></i> Fictional Accel Business catalogue</span><button data-action="privacy">Privacy choices ${icon('arrow')}</button></footer>`;}
function modal(){if(!state.modal)return '';const m=state.modal;let content='';
  if(m.type==='language')content=`<span class="eyebrow">YOUR LANGUAGE. YOUR PACE.</span><h2>Let’s talk your language.</h2><p>The advisor supports English, Hindi and Tamil. Product names and some supporting screens remain in English.</p>${[['en','English'],['hi','हिन्दी'],['ta','தமிழ்']].map(([id,label])=>btn(label,'choose-language','secondary full',`data-language="${id}"`)).join('')}`;
  if(m.type==='privacy')content=`<span class="modal-symbol">${icon('shield')}</span><span class="eyebrow">YOUR DATA, YOUR SAY</span><h2>Privacy is part of the product.</h2><p>This prototype uses fictional businesses and identifiers supplied with the competition case.</p><div class="privacy-detail"><h3>What stays where</h3><p>Documents, OCR text, signatory details, consent and registry inputs stay only in this tab’s memory. They are not uploaded to a server. Refreshing clears them. Non-identifying business preferences and demo order line items use session storage.</p><h3>When you use the advisor</h3><p>Guided mode runs in the browser. If a Gemini or OpenAI key is configured on the local server, your message and basic business preferences go to the configured AI provider. Google’s Gemini free tier may use submitted content to improve its products. Use fictional data only in this demo. Never enter identity numbers or document contents into chat.</p><h3>OCR and external services</h3><p>On-device OCR loads Tesseract.js and its language model from public CDNs. Font files load from Google Fonts. These services receive normal network metadata, but OCR documents are processed locally.</p><h3>Purpose & retention</h3><p>Data is used only to demonstrate recommendations and onboarding. No real identity verification, payments, credit decisions or activation occurs. This is a design choice document, not a claim of legal compliance.</p></div>${btn('Clear all session data','clear-session','danger full')}`;
  if(m.type==='team')content=`<span class="modal-symbol team-modal-mark">pm<span>m</span></span><span class="eyebrow">SMALL TEAM. BIG AMBITIONS.</span><h2>Ping Me Maybe.</h2><p>Udyam Saathi is our Airtel Sync 2026 Digital Track concept: a simpler way for small businesses to discover, choose and get connected.</p><div class="team-note"><b>Built for the case. Designed for people.</b><p>Visual direction inspired by Airtel’s red, white and black identity. This independent student prototype uses the fictional Accel Business catalogue and does not represent an official Airtel service.</p></div>${btn('Back to the workspace','close-modal','primary full')}`;
  if(m.type==='support')content=`<span class="modal-symbol">${icon('users')}</span><span class="eyebrow">TECHNOLOGY WITH A HUMAN SIDE</span><h2>A little help goes a long way.</h2><p>Keep your context when you ask for help. Your business type, team size, city, and current bundle will appear in the partner demo workspace.</p><div class="handoff-preview"><b>${e(BUSINESS_TYPES.find(t=>t.id===state.profile.type)?.name||'Still exploring')}</b><span>${state.profile.employees} people · ${e(state.profile.city)}</span><span>${state.items.length?`${state.items.length} products · ${money(quote().monthly)}/month`:'No bundle selected yet'}</span></div><p class="small-muted">This creates a request inside the prototype only. It does not contact Airtel or send a message to anyone.</p>${btn(`Add to partner demo queue ${icon('arrow')}`,'request-assistance','primary full')}`;
  if(m.type==='product'){const p=productById(state.catalogue,m.id);const reasons=eligibility(p,state.profile,state.items);content=`<span class="modal-symbol">${icon(categoryIcon(p))}</span><span class="eyebrow">${e(p.category)} · ${p.product_id}</span><h2>${e(p.product_name)}</h2><p>${e(p.description)}</p><div class="modal-price">${money(unitPrice(p))}<span> ${e(p.unit)}/month</span></div><dl class="product-detail-list"><div><dt>Catalogue price range</dt><dd>${money(p.price_min_inr_per_month)} – ${money(p.price_max_inr_per_month)}</dd></div><div><dt>One-time setup / unit</dt><dd>${money(p.one_time_setup_inr)}</dd></div><div><dt>Minimum contract</dt><dd>${p.min_contract_months} months</dd></div><div><dt>Typical installation</dt><dd>${p.typical_install_days} days</dd></div><div><dt>Minimum team / locations</dt><dd>${p.min_employees} people / ${p.min_sites} locations</dd></div></dl>${reasons.length?`<div class="alert error">${icon('info')}<div>${reasons.map(x=>`<p>${e(x)}</p>`).join('')}</div></div>`:''}<p class="small-muted">${state.profile.type?'':'Choose your business profile for accurate eligibility. '}Taxes excluded. ${quantityFor(p,state.profile)} ${e(p.unit.replace('per ',''))}${quantityFor(p,state.profile)>1?' units':''} will be added based on your current profile.</p>${btn(`Add to my bundle ${icon('plus')}`,'add-product','primary full',`data-id="${p.product_id}" ${reasons.length?'disabled':''}`)}`;}
  if(m.type==='review'){const d=state.documents[m.kind];content=`<span class="modal-symbol">${icon('file')}</span><span class="eyebrow">CHECK BEFORE YOU CONFIRM</span><h2>Does this look right?</h2><p>${e(d.name)} · ${d.ocr?'Text extracted on your device':'Manual review needed; OCR was unavailable or inconclusive'}</p>${d.preview?`<img class="document-preview" src="${d.preview}" alt="Uploaded document preview">`:''}${d.issues?.length?`<div class="alert error">${icon('info')}<div>${d.issues.map(x=>`<p>${e(x)}</p>`).join('')}</div></div>`:''}${m.kind==='id'?`<label class="field">Name of authorised signatory<input id="doc-confirm-name" value="${e(d.confirmedName||'')}" placeholder="Confirm the name on the document" maxlength="120"></label><label class="field">ID valid until<input id="doc-confirm-expiry" type="date" value="${e(d.validUntil||'')}" min="${CASE_TODAY}"></label>`:''}${['id','address'].includes(m.kind)?`<label class="field">Business name on this document<input id="doc-confirm-business" value="${e(d.businessName||'')}" placeholder="Confirm the business name" maxlength="160"></label>`:''}${m.kind==='address'?`<label class="field">Address proof issue date<input type="date" id="doc-confirm-date" max="${CASE_TODAY}" value="${e(d.billDate||'')}"><small>Must be within 90 days of 15 July 2026.</small></label><label class="field">Business address<input id="doc-confirm-address" value="${e(d.confirmedAddress||'')}" placeholder="Confirm the business address" maxlength="300"></label>`:''}${m.kind==='gst'?`<p class="muted">Read GSTIN: <b>${e(d.gst?maskIdentifier(d.gst):'Not found')}</b></p>`:''}<label class="check-row"><input id="doc-confirm-check" type="checkbox"><span>I checked the original image and confirm these details are accurate for this demo.</span></label><p class="small-muted">This confirmation is a prototype review step, not legal identity verification. Ambiguous or mismatched documents need human review.</p>${btn(`Confirm details ${icon('check')}`,'confirm-doc','primary full',`data-kind="${m.kind}"`)}`;}
  return `<div class="modal-backdrop" data-backdrop="true"><section class="modal ${m.type==='review'?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button>${content}</section></div>`;
}
function render(){const active=document.activeElement;const focused=active?.id;const selection=active?.selectionStart;const scroll=$('.messages')?.scrollTop;const views={overview,advisor,quote:quoteView,products,kyc,tracker,partners,lab:()=>resilienceView(currentLab(),outageAssumptions)};$('#app').innerHTML=`<div class="app-shell">${sidebar()}<div class="workspace">${header()}<main id="main" class="main-content ${state.view}-page">${(views[state.view]||overview)()}</main>${footer()}</div></div>${modal()}`;document.documentElement.lang=hi()?'hi':'en';document.body.classList.toggle('modal-open',!!state.modal);$('.sidebar').inert=window.matchMedia('(max-width:640px)').matches&&!state.mobileNav;const dialog=$('.modal');if(dialog){const h=dialog.querySelector('h2');if(h)h.id='modal-title';dialog.querySelector('button,input')?.focus();}else if(focused&&document.getElementById(focused)){const field=document.getElementById(focused);field.focus({preventScroll:true});try{field.setSelectionRange(selection,selection);}catch{}}if($('.messages'))$('.messages').scrollTop=scroll||$('.messages').scrollHeight;}
function updateProfile(field,value){state.profile[field]=value;if(field==='city')state.profile.tier=['Delhi','Mumbai','Bengaluru','Chennai','Hyderabad','Kolkata','Pune'].includes(value)?1:2;state.quoteAccepted=false;saveProfile();}
async function loadRegistries(){if(!state.consent)throw Error('Consent is required.');if(!state.registries){const generation=consentGeneration;const [gst,udyam]=await Promise.all([fetch('/data/mock_gstin_registry.json').then(r=>r.json()),fetch('/data/mock_udyam_registry.json').then(r=>r.json())]);if(!state.consent||generation!==consentGeneration)throw Error('Consent was withdrawn.');state.registries={gst,udyam};}return state.registries;}
async function sendMessage(text){if(!text.trim()||state.busy)return;state.messages.push({role:'user',text:text.trim()});state.profile=parseMessage(text,state.profile);saveProfile();state.quoteAccepted=false;state.busy=true;render();let reply=advisorReply(text,state.profile,state.catalogue),source='Catalogue-guided demo · rules-based';if(state.live){try{const response=await fetch('/api/advisor',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text,profile:state.profile,history:state.messages.slice(-7,-1)})});const data=await response.json();if(!response.ok)throw Error(data.error||'Live advisor unavailable.');reply=data.reply;if(data.profileUpdates){state.profile={...state.profile,...data.profileUpdates};saveProfile();}source='Live AI · catalogue determines final pricing';}catch(error){source='Guided fallback · live advisor unavailable';toast(error.message||'Live advisor unavailable. Guided mode is still available.');}}state.messages.push({role:'assistant',text:reply,source});state.busy=false;render();$('.messages')?.scrollTo({top:$('.messages').scrollHeight,behavior:'smooth'});$('#chat-input')?.focus();}
let ocrWorker;
let consentGeneration=0;
async function readOcr(blob){if(!ocrWorker){const module=await import('https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.esm.min.js');ocrWorker=await (module.default||module).createWorker('eng',1,{workerPath:'https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/worker.min.js',corePath:'https://cdn.jsdelivr.net/npm/tesseract.js-core@5.1.1',langPath:'https://tessdata.projectnaptha.com/4.0.0'});}const result=await ocrWorker.recognize(blob);return result.data.text;}
async function processFile(file,kind){if(!state.consent)return toast('Please give consent before uploading.');if(file.size>8*1024*1024)return toast('Please choose an image smaller than 8 MB.');if(!['image/png','image/jpeg','image/webp'].includes(file.type))return toast('Choose a PNG, JPG or WebP image.');state.ocrBusy=true;const generation=consentGeneration;const preview=URL.createObjectURL(file);state.documents[kind]={name:file.name,status:'reading',preview,issues:[]};render();try{const text=await Promise.race([readOcr(file),new Promise((_,reject)=>setTimeout(()=>reject(Error('OCR timed out')),25000))]);if(!state.consent||generation!==consentGeneration){URL.revokeObjectURL(preview);return;}const extracted=extractDocument(text,kind);state.documents[kind]={name:file.name,status:'needs-review',preview,ocr:true,...extracted};if(extracted.gstCorrected)toast('An OCR character was corrected using format and checksum checks. Confirm it against the image.');if(kind==='gst'&&extracted.gst&&state.gstResult?.record&&extracted.gst!==state.gstResult.record.gstin)state.documents[kind].issues.push('The GSTIN on this document differs from the verified registry GSTIN.');toast('Document read. Please review and confirm its details.');}catch{if(!state.consent||generation!==consentGeneration){URL.revokeObjectURL(preview);return;}state.documents[kind]={name:file.name,status:'needs-review',preview,ocr:false,issues:[]};toast('OCR could not load. Review the image and enter its details manually.');}finally{state.ocrBusy=false;render();}}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',async event=>{
  if(event.target.closest('[data-backdrop]')===event.target){state.modal=null;render();return;}
  const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;
  try{
    if(a==='nav')return navigate(el.dataset.view);
    if (a === 'lab-preset') {
      outageAssumptions = { ...outageAssumptions, hours: Number(el.dataset.hours) };
      return render();
    }
    if (a === 'lab-download' || a === 'lab-apply') {
      const context = currentLab();
      if (!context.comparison) return;
      if (a === 'lab-download') {
        return download('UdyamSaathi_Resilience_Decision.txt', decisionReceipt(context, outageAssumptions));
      }
      if (context.sample || !['without', 'withBackup'].includes(el.dataset.choice)) return;
      state.items = context.comparison[el.dataset.choice];
      state.quoteAccepted = false;
      return navigate('quote');
    }
    if(a==='nav-quote')return navigate('quote');
    if(a==='menu'){state.mobileNav=!state.mobileNav;return render();}
    if(a==='start'){navigate('advisor');return;}
    if(a==='back-advisor')return navigate('advisor');
    if(a==='language'){state.modal={type:'language'};return render();}if(a==='choose-language'){state.profile.language=el.dataset.language;saveProfile();state.modal=null;render();return toast('Advisor language updated.');}
    if(['privacy','team','support'].includes(a)){state.modal={type:a};return render();}
    if(a==='close-modal'){state.modal=null;return render();}
    if(a==='business-type'){updateProfile('type',el.dataset.type);if(state.profile.type==='multi'&&state.profile.sites<3)state.profile.sites=3;render();return;}
    if(a==='recommend'){state.items=recommend(state.profile,state.catalogue);state.quoteAccepted=false;return navigate('quote');}
    if(a==='category'){state.category=el.dataset.category;state.search='';return navigate('products');}
    if(a==='product-detail'){state.modal={type:'product',id:el.dataset.id};return render();}
    if(a==='add-product'){const p=productById(state.catalogue,el.dataset.id);if(eligibility(p,state.profile,state.items).length)return;state.items.push({id:p.product_id,qty:quantityFor(p,state.profile),reason:p.description});state.quoteAccepted=false;state.modal=null;render();return toast(`${p.product_name} added to your bundle.`);}
    if(a==='remove-product'){state.items=state.items.filter(i=>i.id!==el.dataset.id);state.quoteAccepted=false;render();return;}
    if(a==='quantity'){const item=state.items.find(i=>i.id===el.dataset.id);item.qty=Math.max(1,Math.min(10000,item.qty+Number(el.dataset.delta)));state.quoteAccepted=false;return render();}
    if(a==='accept-quote'){if(quote().errors.length)return;state.quoteAccepted=true;return navigate('kyc');}
    if(a==='verify-gst'||a==='verify-udyam'){const reg=await loadRegistries();if(a==='verify-gst'){state.gstInput=$('#gst-input').value.trim().toUpperCase();state.gstResult=checkGstin(state.gstInput,reg.gst);}else{state.udyamInput=$('#udyam-input').value.trim().toUpperCase();state.udyamResult=checkUdyam(state.udyamInput,reg.udyam);}state.kycErrors=[];return render();}
    if(a==='demo-registry'){const reg=await loadRegistries();if(!state.consent)return;const r=reg.gst.find(r=>r.gstin==='27XUIXG0767D1ZP');state.gstInput=r.gstin;state.gstResult=checkGstin(r.gstin,reg.gst);const u=reg.udyam.find(u=>(u.enterprise_name===r.legal_name||u.enterprise_name===r.trade_name)&&u.state===r.state);if(u){state.udyamInput=u.udyam_number;state.udyamResult=checkUdyam(u.udyam_number,reg.udyam);}render();return toast('Fictional business loaded from the supplied registry.');}
    if(a==='demo-docs'){for(const [kind,filename] of [['id','K03_signatory_id.png'],['address','K03_address_proof.png']]){const response=await fetch(`/data/kyc_documents/${filename}`);if(!response.ok)throw Error('Sample document unavailable.');const blob=await response.blob();await processFile(new File([blob],filename,{type:'image/png'}),kind);}return;}
    if(a==='review-doc'){state.modal={type:'review',kind:el.dataset.kind};return render();}
    if(a==='remove-doc'){const d=state.documents[el.dataset.kind];if(d?.preview)URL.revokeObjectURL(d.preview);delete state.documents[el.dataset.kind];return render();}
    if(a==='confirm-doc'){const kind=el.dataset.kind,d=state.documents[kind];if(!$('#doc-confirm-check')?.checked)return toast('Please confirm you checked the original document.');if(['id','address'].includes(kind)){d.businessName=$('#doc-confirm-business').value.trim();if(d.businessName.length<2)return toast('Confirm the business name on the document.');}if(kind==='id'){const name=$('#doc-confirm-name').value.trim();if(name.length<2)return toast('Enter the authorised signatory name.');d.confirmedName=name;d.validUntil=$('#doc-confirm-expiry').value;if(!d.validUntil)return toast('Confirm the ID expiry date.');d.issues=d.issues.filter(x=>!x.startsWith('Signatory ID'));if(d.validUntil<CASE_TODAY){d.issues.push('Signatory ID is expired at the case reference date.');render();return toast('This signatory ID is expired.');}}if(kind==='address'){d.billDate=$('#doc-confirm-date').value;d.confirmedAddress=$('#doc-confirm-address').value.trim();if(!d.billDate||!d.confirmedAddress)return toast('Confirm the issue date and business address.');const age=(Date.parse(CASE_TODAY)-Date.parse(d.billDate))/86400000;d.issues=d.issues.filter(x=>!x.startsWith('Address proof'));if(age<0||age>90){d.issues.push('Address proof must be within 90 days of the case reference date.');render();return toast('This proof is outside the accepted date window.');}}d.status='reviewed';state.modal=null;state.kycErrors=[];render();return toast('Document details confirmed for demo review.');}
    if(a==='place-order'){const q=quote();const errors=[...q.errors,...validateKyc({consent:state.consent,gstResult:state.gstResult,udyamResult:state.udyamResult,documents:state.documents,quote:q})];if(state.gstResult?.ok&&state.udyamResult?.ok){const norm=s=>s.toLowerCase().replace(/[^a-z0-9]/g,'');if((norm(state.gstResult.record.legal_name)!==norm(state.udyamResult.record.enterprise_name)&&norm(state.gstResult.record.trade_name)!==norm(state.udyamResult.record.enterprise_name))||state.gstResult.record.state!==state.udyamResult.record.state)errors.push('GST and Udyam enterprise details differ. Please check the registrations or request assistance.');}for(const d of Object.values(state.documents))errors.push(...(d.issues||[]));if(errors.length){state.kycErrors=[...new Set(errors)];render();$('.alert.error')?.scrollIntoView({behavior:'smooth',block:'center'});return;}state.order={id:`PMM-${Date.now().toString(36).toUpperCase()}`,created:new Date().toISOString(),lines:q.lines,monthly:q.monthly,setup:q.setup,installDays:q.installDays,contract:q.contract};state.orderStep=0;saveOrder();navigate('tracker');return toast('Demo order submitted. No payment or real activation has occurred.');}
    if(a==='advance-order'){state.orderStep=(state.orderStep+1)%4;saveOrder();return render();}
    if(a==='download-order'){const o=state.order;return download(`PingMeMaybe_${o.id}.txt`,`PING ME MAYBE — UDYAM SAATHI\nDEMO ORDER — NOT A REAL SERVICE ORDER\n\nOrder: ${o.id}\nCreated: ${new Date(o.created).toLocaleString('en-IN')}\nStatus: ${ORDER_STAGES[state.orderStep][0]}\n\n${o.lines.map(l=>`${l.product.product_name} x ${l.qty}: INR ${l.monthly}/month; setup INR ${l.setup}; minimum ${l.product.min_contract_months} months`).join('\n')}\n\nMonthly total: INR ${o.monthly} (taxes excluded)\nOne-time setup: INR ${o.setup}\nLongest minimum contract: ${o.contract} months\nTypical installation: up to ${o.installDays} days, subject to serviceability\n\nPrices use the lower catalogue range from the supplied synthetic Accel Business case. No payment, live KYC or real activation occurs.\nTeam: Ping Me Maybe | Airtel Sync 2026\n`);}
    if(a==='request-assistance'){state.assistance=true;state.modal=null;render();return toast('Request added to the partner demo queue. No external message sent.');}
    if(a==='resolve-assistance'){state.assistance=false;render();return toast('Demo assistance request marked as reviewed.');}
    if(a==='clear-session'){for(const d of Object.values(state.documents))if(d.preview)URL.revokeObjectURL(d.preview);sessionStorage.removeItem('saathi-profile');sessionStorage.removeItem('saathi-order');location.href='/';return;}
  }catch(error){toast(error.message||'Something went wrong. Please try again.');}
});
document.addEventListener('submit', event => {
  const form = event.target;
  if (form.id !== 'outage-form') return;
  event.preventDefault();
  if (!form.reportValidity()) return;
  const values = new FormData(form);
  outageAssumptions = Object.fromEntries(outageFields.map(({ key }) => [key, Number(values.get(key))]));
  render();
});
document.addEventListener('submit',event=>{if(event.target.id==='chat-form'){event.preventDefault();const value=$('#chat-input').value;$('#chat-input').value='';sendMessage(value);}});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.field){let value=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;if(el.type==='number'){value=Math.max(Number(el.min),Math.min(Number(el.max),Number.isFinite(value)?value:Number(el.min)));el.value=value;}updateProfile(el.dataset.field,value);render();}if(el.id==='kyc-consent'){state.consent=el.checked;if(!el.checked){consentGeneration++;state.gstInput='';state.udyamInput='';state.gstResult=null;state.udyamResult=null;state.registries=null;for(const d of Object.values(state.documents))if(d.preview)URL.revokeObjectURL(d.preview);state.documents={};}state.kycErrors=[];render();}if(el.dataset.upload&&el.files?.[0])processFile(el.files[0],el.dataset.upload);});
document.addEventListener('input',event=>{if(event.target.id==='product-search'){state.search=event.target.value;render();}if(event.target.id==='gst-input'){state.gstInput=event.target.value;state.gstResult=null;}if(event.target.id==='udyam-input'){state.udyamInput=event.target.value;state.udyamResult=null;}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.modal){state.modal=null;render();}if(event.key==='Tab'&&state.modal){const els=[...document.querySelectorAll('.modal button:not(:disabled),.modal input:not(:disabled),.modal a[href]')];const first=els[0],last=els.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
async function init(){try{const [catalogue,insights]=await Promise.all([fetch('/data/product_catalogue.json').then(r=>r.json()),fetch('/data/insights.json').then(r=>r.json())]);state.catalogue=catalogue;state.insights=insights;render();fetch('/api/health').then(r=>r.json()).then(data=>{state.live=data.advisor==='live';if(state.view==='advisor')render();}).catch(()=>{});}catch{$('#app').innerHTML='<div class="boot"><span class="boot-mark">u.</span><h1>A connection hiccup.</h1><p>The product catalogue could not load. Please refresh to try again.</p><button onclick="location.reload()">Try again</button></div>';}}
init();
